	path := filepath.Join(t.TempDir(), "grammars.json")
	original := `[
  {
    "language": "fsharp",
    "url": "https://github.com/ionide/tree-sitter-fsharp",
    "reference": "main",
    "revision": "02929f0",
    "path": "fsharp",
