func maskSwiftChainedDotLines(lines []string, start int) int {
	last := start - 1
	for i := start; i < len(lines); i++ {
		text, newline := splitLineEnding(lines[i])
		if !strings.HasPrefix(strings.TrimSpace(text), ".") {
			return last
		}
		lines[i] = maskLineText(text) + newline
