// kotlinModifiedPropTypedRe.
const swiftModifierPattern = `(?:(?:public|private|fileprivate|internal|open|package|static|class|final|lazy|weak|unowned|override|required|nonisolated|indirect)(?:\(\w+\))?\s+)`

