				EvidenceKind: "kubernetes_resource",
			}}
			targets = append(targets, kubernetesResourceConfigTargets(content)...)
			return targets
		}
		if isKubernetesPath(symbol.FilePath) || looksLikeKubernetesManifest(content) {
			return []configTarget{{
				Name:         "kubernetes/" + symbol.Name,
				Confidence:   0.75,
				Reason:       "YAML manifest configures a Kubernetes resource",
				EvidenceKind: "kubernetes_yaml",
			}}
// same-file symbol slice per reference (firstTypeLikeNamed), so the pass costs
// symbols x references x symbols-in-file: it is QUADRATIC in symbols per file,
// not the single linear pass the other producers are. Measured on one 16k-symbol
// TypeScript file it charged 5.2 s to an already-expired budget, so it takes the
// stop predicate rather than relying on the caller's guard between stages, which
// cannot run until the whole slice has been materialized.
func usesTypeRelations(stop func() bool, recordsByFile map[string][]SymbolRecord, symbolsByFile, symbolsByShortName map[string][]SymbolRecord, resolvedImportsByFile map[string]map[string][]string) []RelationRecord {
	paths := make([]string, 0, len(recordsByFile))
	for path := range recordsByFile {
		paths = append(paths, path)
	}
	sort.Strings(paths)

	var relations []RelationRecord
	for _, path := range paths {
		if stop != nil && stop() {
			return relations
		}
		for _, symbol := range recordsByFile[path] {
			if stop != nil && stop() {
				return relations
			}
			if symbol.Kind != "function" && symbol.Kind != "method" || symbol.Signature == "" {
				continue
			}
			importsByName := resolvedImportsByFile[path]
			qualifiedImportsByName := qualifiedTypeImports(symbol.Signature, importsByName)
			names := make([]string, 0)
			seen := map[string]bool{}
			for name := range identifiersIn(symbol.Signature) {
				if name == symbol.Name || seen[name] {
					continue
				}
				seen[name] = true
				names = append(names, name)
			}
			sort.Strings(names)
			emitted := map[string]bool{}
			for _, name := range names {
				target, resolution, scope, confidence, ok := resolveTypeReference(name, symbol, symbolsByFile[path], symbolsByShortName, importsByName, qualifiedImportsByName)
				if !ok || emitted[target.ID] {
					continue
				}
				emitted[target.ID] = true
				relations = append(relations, RelationRecord{
					RecordType:    "relation",
					FromID:        symbol.ID,
					ToID:          target.ID,
					Type:          "USES_TYPE",
					Confidence:    confidence,
					Reason:        "type referenced in signature",
					RelationScope: scope,
					Resolution:    resolution,
					TargetKind:    "symbol",
					Evidence: []Evidence{{
						Kind:      "signature",
						FilePath:  symbol.FilePath,
						StartLine: symbol.StartLine,
						EndLine:   symbol.EndLine,
						Detail:    name,
					}},
					WarningCodes: []string{},
				})
			}
		}
	}
	return relations
}

