      seq($._equal_sign, field("value", $._expression)),
    willset_didset_block: ($) =>
      choice(
        seq("{", $.willset_clause, optional($.didset_clause), "}"),
        seq("{", $.didset_clause, optional($.willset_clause), "}")
      ),
    willset_clause: ($) =>
      seq(
        optional($.modifiers),
        "willSet",
        optional(seq("(", $.simple_identifier, ")")),
        $._block
      ),
    didset_clause: ($) =>
      seq(
        optional($.modifiers),
        "didSet",
        optional(seq("(", $.simple_identifier, ")")),
        $._block
      ),
    typealias_declaration: ($) =>
      seq(optional($.modifiers), $._modifierless_typealias_declaration),
    _modifierless_typealias_declaration: ($) =>
      seq(
        "typealias",
        field("name", alias($.simple_identifier, $.type_identifier)),
	for _, field := range []string{"result", "return_type", "returns", "type"} {
		if found := node.ChildByFieldName(field); validNode(found) {
			return found
		}
	}
