	for index := 0; index < int(node.NamedChildCount()); index++ {
		child := node.NamedChild(index)
		if !isTypeNode(child) {
			continue
		}
		if nodeWithinParameterLists(child, lists) {
			continue // a parameter's own type, not the result
		}
		if nodeAfterParameterLists(child, lists) {
			return child
		}
		if beforeLists == nil {
			beforeLists = child
		}
